import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = r.nextLong();
        Arrays.sort(a);
        long[] values = new long[n], counts = new long[n];
        int d = 0;
        for (int i = 0; i < n; i++) {
            if (d == 0 || values[d - 1] != a[i]) { values[d] = a[i]; counts[d++] = 0; }
            counts[d - 1]++;
        }
        long[] prefix = new long[d + 1];
        int left = 0;
        long answer = 0;
        for (int i = 0; i < d; i++) {
            prefix[i + 1] = prefix[i] + counts[i];
            if (i > 0 && values[i] != values[i - 1] + 1) left = i;          // gap: restart
            else if (i > 0 && counts[i - 1] == 1) left = Math.max(left, i - 1);  // a single copy can only be an endpoint
            answer = Math.max(answer, prefix[i + 1] - prefix[left]);
        }
        System.out.println(answer);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	slices.Sort(a)
	var values, counts []int
	for _, v := range a {
		if len(values) == 0 || values[len(values)-1] != v {
			values = append(values, v)
			counts = append(counts, 0)
		}
		counts[len(counts)-1]++
	}
	prefix := []int{0}
	left, answer := 0, 0
	for i, v := range values {
		prefix = append(prefix, prefix[i]+counts[i])
		if i > 0 && v != values[i-1]+1 { // gap: restart
			left = i
		} else if i > 0 && counts[i-1] == 1 { // a single copy can only be an endpoint
			left = max(left, i-1)
		}
		answer = max(answer, prefix[i+1]-prefix[left])
	}
	fmt.Println(answer)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
